function buildMemberPage(members, page, pageSize, selectedId) {
  if (!Array.isArray(members)) throw new TypeError('members must be an array');
  if (!Number.isInteger(page) || !Number.isInteger(pageSize) || page < 1 || pageSize < 1) {
    throw new RangeError('page values must be positive integers');
  }
  if (selectedId !== null && typeof selectedId !== 'string') throw new TypeError('invalid selectedId');

  const ids = new Set();
  for (const member of members) {
    if (!member || typeof member !== 'object' || Array.isArray(member) ||
        typeof member.id !== 'string' || typeof member.displayName !== 'string') {
      throw new TypeError('invalid member');
    }
    if (ids.has(member.id)) throw new RangeError('duplicate member id');
    ids.add(member.id);
  }

  const start = (page - 1) * pageSize;
  const entries = members.slice(start, start + pageSize).map(member => ({ ...member }));
  const match = selectedId === null ? undefined : members.find(member => member.id === selectedId);

  return {
    entries,
    page,
    pageSize,
    totalEntries: members.length,
    totalPages: members.length === 0 ? 0 : Math.floor(members.length / pageSize),
    selected: match ? { ...match } : null
  };
}

module.exports = { buildMemberPage };

