'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['buildMemberPage']);
const { buildMemberPage } = api;

const members = [
  { id: 'a', displayName: 'Ada', role: 'admin' },
  { id: 'b', displayName: 'Ben' },
  { id: 'c', displayName: 'Cy' },
  { id: 'd', displayName: 'Dee' },
  { id: 'e', displayName: 'Eli' }
];
const snapshot = members.map(member => ({ ...member }));
const result = buildMemberPage(members, 2, 2, 'a');
assert.deepStrictEqual(result, {
  entries: [{ id: 'c', displayName: 'Cy' }, { id: 'd', displayName: 'Dee' }],
  page: 2,
  pageSize: 2,
  totalEntries: 5,
  totalPages: 3,
  selected: { id: 'a', displayName: 'Ada', role: 'admin' }
});
assert.notStrictEqual(result.entries[0], members[2]);
assert.notStrictEqual(result.selected, members[0]);
result.entries[0].displayName = 'changed';
result.selected.role = 'changed';
assert.deepStrictEqual(members, snapshot);

assert.deepStrictEqual(buildMemberPage([], 1, 3, null), {
  entries: [], page: 1, pageSize: 3, totalEntries: 0, totalPages: 0, selected: null
});
assert.deepStrictEqual(buildMemberPage(members, 4, 2, 'missing').entries, []);
assert.strictEqual(buildMemberPage(members, 1, 5, 'missing').selected, null);

assert.throws(() => buildMemberPage({}, 1, 1, null), TypeError);
assert.throws(() => buildMemberPage([null], 1, 1, null), TypeError);
assert.throws(() => buildMemberPage([[]], 1, 1, null), TypeError);
assert.throws(() => buildMemberPage([{ id: 1, displayName: 'A' }], 1, 1, null), TypeError);
assert.throws(() => buildMemberPage([{ id: 'a', displayName: 1 }], 1, 1, null), TypeError);
assert.throws(() => buildMemberPage([{ id: 'x', displayName: 'X' }, { id: 'x', displayName: 'Y' }], 1, 1, null), RangeError);
for (const page of [0, -1, 1.5, NaN]) assert.throws(() => buildMemberPage([], page, 1, null), RangeError);
for (const size of [0, -1, 1.5, Infinity]) assert.throws(() => buildMemberPage([], 1, size, null), RangeError);
assert.throws(() => buildMemberPage([], 1, 1, undefined), TypeError);

